UPDATE SETTINGS SET VALUE = 'С уважением, {23}!' WHERE EXT_ID = 'GratitudeUp';
UPDATE SETTINGS SET VALUE = 'Данное письмо отправлено с адреса, предназначенного            только для рассылок. Пожалуйста, не отвечайте на это письмо. В случае возникновения            вопросов Вы можете обратиться к персональному менеджеру, контактные данные есть в            «личном кабинете» или по телефону <br> {21} (звонок бесплатный).' WHERE EXT_ID = 'GratitudeDown';
UPDATE SETTINGS SET VALUE = '<p> Мы не храним ваши пароли.<br /> Если вы забыли свой пароль или у вас не получается войти в Личный кабинет — воспользуйтесь формой восстановления пароля по ссылке <a class="no_block" href="{0}">«Забыли пароль?»</a>. </p> <div class="instruction"> <p class="instruction_text"> <span class="mark">&nbsp;</span> Для восстановления данных укажите ваш логин. </p> <p class="instruction_text"> <span class="mark">&nbsp;</span> На ваш адрес электронной почты будет отправлена ссылка для восстановления пароля.<br /> <span style="margin-left: 19px">Срок действия ссылки {7}.</span> </p> </div>' WHERE EXT_ID = 'emailPasswordFooterHtml';
UPDATE SETTINGS SET VALUE = '<p class="small_text login_data"> Ваш логин:<br /> <span class="text_bolid">{32}</span> </p>' WHERE EXT_ID = 'emailLoginHtml';
UPDATE SETTINGS SET VALUE = '<p class="small_text login_data"> Ваш логин:<br /> <span class="text_bolid">{22}</span><br /> <span class="small_text">или</span><br /> <span class="text_bolid">{2}</span> </p>' WHERE EXT_ID = 'emailLoginAndPhoneHtml';

UPDATE SETTINGS SET VALUE = '<p> Ваша учетная запись для входа в Личный кабинет «{23}» <font color="{28}">заблокирована</font>. Доступ к услугам при этом не блокируется.<br> Вы не использовали свою учетную запись в течении длительного времени. Чтобы восстановить доступ к учетной записи, обратитесь к своему персональному менеджеру или оставьте заявку в чате <a class="no_block" href="{0}">на сайте</a> или по телефону <a class="no_block" href="tel:{24}">{21}</a>. </p> {19} {20}' WHERE EXT_ID = 'blockNotificationSchedulerHtml';
UPDATE SETTINGS SET VALUE = '<p> Ваша учетная запись для входа в <a href="{0}">Личный кабинет</a> «{23}» <span style="color: {29}"> разблокирована.</span> </p> {19} <p class = "block_login"> <a class="no_block" href="{0}"> Перейти в Личный кабинет</a> </p>' WHERE EXT_ID = 'emailEnabledAccountBodyHtml';
UPDATE SETTINGS SET VALUE = '<p> Подтвердите вашу учетную запись для входа в Личный кабинет «{23}». Срок действия ссылки {6}. </p> <p class="block_link"> <a href="{12}">Подтвердить учетную запись</a> </p>' WHERE EXT_ID = 'emailVerificationLoginBodyHtml';
UPDATE SETTINGS SET VALUE = '<p> Код для подтверждения данных вашей учетной записи Личного кабинета «{23}»: </p> <p style="font-weight: bold" class="text_bolid margin_block"> {4} </p>' WHERE EXT_ID = 'emailVerificationAuthBodyHtml';
UPDATE SETTINGS SET VALUE = '<p> Создана учетная запись <a class="no_block" href="mailto:{3}">{3}</a>. Если ее создали вы, пройдите по ссылке ниже для подтверждения вашего e-mail. </p> <p style="margin-top: 16px; margin-bottom: 16px;" class="block_link"><a href="{12}">Подтвердить e-mail</a></p> <p style="font-size: 12px; line-height: 16px;" class="small_text"> Эта ссылка устареет через {6}.<br> Если вы не создавали учетную запись, просто проигнорируйте это письмо. </p>' WHERE EXT_ID = 'emailVerificationBodyHtml';
UPDATE SETTINGS SET VALUE = '<p> Для безопасности ваших персональных данных пароль от входа в личный кабинет «{23}» был сброшен. Чтобы восстановить учетную запись, перейдите по ссылке ниже и смените пароль. </p> <p style="margin-top: 16px" class="block_link"> <a href="{11}">Восстановить пароль</a> </p>' WHERE EXT_ID = 'emailCredentialDisableBodyHtml';
UPDATE SETTINGS SET VALUE = '<p> Ваша учетная запись для входа в Личный кабинет «{23}» <font color="{28}">заблокирована</font>. Доступ к услугам при этом не блокируется.<br> Чтобы восстановить доступ к учетной записи, обратитесь к своему персональному менеджеру или оставьте заявку в чате <a class="no_block" href="{0}">на сайте</a> или по телефону <a class="no_block" href="tel:{24}">{21}</a>. </p> {19} {20}' WHERE EXT_ID = 'emailDisabledAccountBodyHtml';
UPDATE SETTINGS SET VALUE = '<p> Для вас создана учетная запись для входа в <a href="{0}">Личный кабинет</a> </p> <p class="small_text block_timer">Срок действия ссылки {7}.</p> {19} <p style="margin-top: 16px"> Благодарим вас за выбор услуг «{23}» для вашей компании! </p>' WHERE EXT_ID = 'emailAccountCreateBodyHtml';
UPDATE SETTINGS SET VALUE = '<p> Для авторизации в <a class="no_block" href="{0}">Личном кабинете</a> необходимо указать логин и пароль, установленный вами при регистрации в Личном кабинете. </p> {19} {20} <p class = "block_login"> <a class="no_block" href="{0}"> Перейти в Личный кабинет</a> </p>' WHERE EXT_ID = 'emailSendLoginBodyHtml';
UPDATE SETTINGS SET VALUE = '<p> Для вас создана учетная запись для входа в <a href="{0}">Личный кабинет</a> </p> <p class="small_text block_timer">Срок действия ссылки {7}.</p> {19} <p style="margin-top: 16px"> Пройдите по ссылке и <a href="{13}">установите пароль</a> </p>' WHERE EXT_ID = 'emailAccountDataBodyHtml';
UPDATE SETTINGS SET VALUE = '<p> Пароль вашей учетной записи был сброшен.<br /> Установите новый пароль по <a class="no_block" href="{11}">ссылке</a>, чтобы завершить процесс и восстановить доступ к личному кабинету. </p> <p class="small_text block_timer">Срок действия ссылки {7}.</p> {19} <p class = "block_login"> <a class="no_block" href="{0}">Перейти в Личный кабинет</a> </p> {20}' WHERE EXT_ID = 'emailResetPasswordBodyHtml';
UPDATE SETTINGS SET VALUE = '<p> Был создан запрос на изменение пароля от вашей учетной записи <a href="mailto:{3}">{3} </a>. Если это были вы, пройдите по ссылке: <br /> </p> <a href="{12}" style="margin-top: 16px">Изменить пароль</a> <p class="content__secondary content__secondary-mt"> Эта ссылка устареет через {6} <br /> Если вы не хотите сбрасывать пароль, просто проигнорируйте это письмо. </p>' WHERE EXT_ID = 'passwordResetBodyHtml';
UPDATE SETTINGS SET VALUE = '<p> Просим вас обновить данные учетной записи <a class="no_block" href="mailto:{3}">{3}</a>. Для этого перейдите по ссылке ниже. </p> <p style="margin-top: 16px; margin-bottom: 16px" class="block_link"> <a href="{12}">Обновить данные</a> </p> <p style="font-size: 12px; line-height: 16px" class="small_text"> Эта ссылка устареет через {5}. </p>' WHERE EXT_ID = 'executeActionsBodyHtml';
